def detect_duplicate(movement, others):
    import math
    from datetime import timedelta
    from dateutil.relativedelta import relativedelta

    # Criterio 1: Mismo monto (tolerancia 0.01)
    def same_amount(mv1, mv2):
        same_amt1 = mv1['creditAmount'] if mv1['creditAmount'] else mv1['debitAmount']
        same_amt2 = mv2['creditAmount'] if mv2['creditAmount'] else mv2['debitAmount']
        return abs(same_amt1 - same_amt2) < 0.01

    # Criterio 2: Referencia exactamente igual
    def same_reference(mv1, mv2):
        return (mv1['reference'] and mv2['reference'] and mv1['reference'] == mv2['reference'])

    # Criterio 2b: Similitud de descripción (usando un esquema estándar: trigram similarity)
    def trigram_similarity(s1, s2):
        from difflib import SequenceMatcher
        if not s1 or not s2:
            return 0.0
        matcher = SequenceMatcher(None, s1, s2)
        return matcher.ratio()

    # Criterio 3: Ventana de fechas (≤ 3 días hábiles)
    def is_within_days(date1, date2, max_days=3):
        day_diff = abs((date2.date() - date1.date()).days)
        if day_diff <= max_days:
            return True
        return False

    # Recorrer los otros movimientos
    for other in others:
        if other['id'] == movement['id']:
            continue

        if not same_amount(movement, other):
            continue

        if not same_reference(movement, other) and trigram_similarity(
            movement.get('description', ''), other.get('description', '')
        ) <= 0.8:
            continue

        if not is_within_days(movement['transactionDate'], other['transactionDate']):
            continue

        # Determinar confianza y razón
        if same_reference(movement, other):
            confidence = 0.95
            reason = f"Misma referencia y monto que movimiento del {other['transactionDate']}"
        else:
            confidence = 0.85
            reason = f"Descripción y monto similares a movimiento del {other['transactionDate']}"

        return {
            'isDuplicate': True,
            'originalMovementId': other['id'],
            'confidence': confidence,
            'reason': reason
        }

    return None

